using System.Collections.ObjectModel;using OdinVault.Manager.Wpf.Infrastructure;using OdinVault.Manager.Wpf.Services;namespace OdinVault.Manager.Wpf.ViewModels;internal sealed class AlertsViewModel:ObservableObject{readonly AgentDashboardClient c;bool loading;string? error;int unread;public ObservableCollection<AlertRow> Items{get;}=[];public bool IsLoading{get=>loading;private set=>Set(ref loading,value);}public string? Error{get=>error;private set=>Set(ref error,value);}public int Unread{get=>unread;private set=>Set(ref unread,value);}public AlertsViewModel(AgentDashboardClient c)=>this.c=c;public async Task LoadAsync(){IsLoading=true;Error=null;try{var x=await c.AlertsAsync();if(x is null)return;Unread=x.UnreadCount;Items.Clear();foreach(var a in x.Alerts)Items.Add(new(a.Severity,a.Category,a.DatabaseName,a.Title,a.Message,a.OccurredAtUtc.ToLocalTime().ToString("yyyy/MM/dd HH:mm"),a.IsRead?"خوانده‌شده":"جدید"));}catch(Exception e){Error=e.Message;}finally{IsLoading=false;}}}internal sealed record AlertRow(string Severity,string Category,string Database,string Title,string Message,string Time,string State);